fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}fn save(n:&str,v:&Value){fs::write(format!("{R}/{n}"),serde_json::to_vec_pretty(v).unwrap()).unwrap();}
fn main(){assert!(!Path::new(&format!("{R}/plan.json")).exists());let mut pins=BTreeMap::<String,String>::new();let mp=format!("{Z}/docs/benchmarks/2026-10-30-g2-vector-sign-adoption176/artifacts/production-source-manifest.json");let m=read(&mp);assert_eq!(m["source_files_sha256"].as_object().unwrap().len(),176);for(p,h)in m["source_files_sha256"].as_object().unwrap(){let path=format!("{Z}/{p}");assert_eq!(hash(&path),h.as_str().unwrap());pins.insert(path,h.as_str().unwrap().into());}pins.insert(mp.clone(),hash(&mp));let prior_inputs=read(format!("{OLD}/inputs.json"));let original=fs::read_to_string(prior_inputs["decomposition_source"].as_str().unwrap()).unwrap();let split=fs::read(format!("{OLD}/split.rs")).unwrap();assert_eq!(split,&original.as_bytes()[prior_inputs["exact_slice_start"].as_u64().unwrap()as usize..prior_inputs["exact_slice_end"].as_u64().unwrap()as usize]);fs::write(format!("{R}/split.rs"),split).unwrap();for k in["fixture","oracle"]{let p=prior_inputs["fixture"][k].as_str().unwrap();pins.insert(p.to_string(),hash(p));}assert_eq!(hash(prior_inputs["fixture"]["fixture"].as_str().unwrap()),prior_inputs["oracle"]["fixture_sha256"].as_str().unwrap());assert_eq!(prior_inputs["oracle"]["independent_Arkworks_complete_MSM"],true);let old_analysis=read(format!("{OLD}/analysis.json"));let old_review=read(format!("{OLD}/review.json"));assert_eq!(old_review["review_passed"],true);let baseline=old_analysis["original_radix_all_including_indexed_top_hypothetical_dense"].clone();assert_eq!(baseline["generic_addition_model_total"],634405);save("baseline.json",&baseline);save("inputs.json",&prior_inputs);for name in["inputs.json","split.rs","analysis.json","review.json"]{let p=format!("{OLD}/{name}");pins.insert(p.clone(),hash(p));}let external=format!("{R}/research/ecmult_impl.h");let text=fs::read_to_string(&external).unwrap();assert!(text.contains("static int secp256k1_wnaf_fixed"));assert!(text.contains("skew = 1"));save("prior-art.json",&json!({"url":"https://github.com/bitcoin-core/secp256k1/blob/cc0e03ffd4ddfce3663dc807a10cc4e3d0132d79/src/ecmult_impl.h","commit":"cc0e03ffd4ddfce3663dc807a10cc4e3d0132d79","source_sha256":hash(&external),"source_not_copied_or_benchmarked":true,"private_external_source":external,"independent_recipe_differences":["final-window unit collapse included","separate correction point-sum tree in model","BN254 component magnitude and 11-window specialization"]}));pins.insert(external.clone(),hash(external));for name in["design.md","setup.rs","screen.rs","split.rs","baseline.json","inputs.json","prior-art.json","research/ecmult-commits.json"]{let p=format!("{R}/{name}");pins.insert(p.clone(),hash(p));}save("pins.json",&json!(pins));let t="/home/ubuntu/.rustup/toolchains/1.98.1-x86_64-unknown-linux-gnu/bin/rustc";let d="/home/ubuntu/src/zopro-perf-work/tool-target/release/deps";let steps=json!([{"kind":"command","name":"compile-screen","argv":[t,"--edition=2021","-O","-L",format!("dependency={d}"),"--extern",format!("serde_json={d}/libserde_json-cdebb9338c2784ad.rlib"),"--extern",format!("sha2={d}/libsha2-16b8f2c03bdf5faa.rlib"),format!("{R}/screen.rs"),"-o",format!("{R}/screen")],"environment":{},"timeout_seconds":180},{"kind":"command","name":"count-screen","argv":[format!("{R}/screen")],"environment":{},"timeout_seconds":180}]);save("plan.json",&json!({"version":1,"source_pins":format!("{R}/pins.json"),"steps":steps}));println!("Sealed fixed width12 odd/skew recipe;original176exact;full11window control634405inherited;2newsteps/no native proof benchmark");}
